page(s,[('Последовательность',['Период прошлых выходных, переход затем и итог рассказа выполняют разные функции. В задачах порядок дан прямо.'],[W['le-week-end-dernier']['example'],W['finalement']['example']]),('Два выбранных перемещения',['Показаны только поход и возвращение. Выбор вспомогательного глагола учится в этих моделях и не расширяется автоматически на все перемещения.'],[W['etre-pc']['example'],ex('Je suis rentré à la maison.','Я вернулся домой (мужская форма).','жё сюи ра(н)трэ а ла мэзо́(н)')]),('Письмо и звучание',['Женские формы двух показанных действий отличаются дополнительной буквой на письме; звучание такое же. Голос не используется для угадывания пола говорящего.'],[ex('Je suis allée au musée. Je suis rentrée à la maison.','Я сходила в музей. Я вернулась домой.','жё сюи залэ о мюзэ́. жё сюи ра(н)трэ а ла мэзо́(н)')])])
