page(s,[('Положительное впечатление',['Знакомые действия любить занятие и обожать возвращаются в прошедшем времени. Более сильная положительная оценка отличается от обычного понравилось.'],[ex('J’ai aimé visiter le musée.','Мне понравилось посещать музей.','жэ эмэ визитэ лё мюзэ́'),ex('J’ai adoré visiter le musée.','Я был в восторге от посещения музея.','жэ адорэ визитэ лё мюзэ́')]),('Отрицательная оценка',['В изученной форме отрицание охватывает вспомогательную часть, а вторая часть стоит перед понравилось.'],[ex('Je n’ai pas aimé regarder le film.','Мне не понравилось смотреть фильм.','жё нэ па эмэ рёгардэ лё фи́льм')]),('Событие и впечатление',['Просмотр фильма и отношение к нему — разные сведения. Не понравилось смотреть не отменяет прямо названный факт просмотра.'],[ex('J’ai regardé un film. Je n’ai pas aimé regarder le film.','Я посмотрел фильм. Мне не понравилось смотреть этот фильм.','жэ рёгардэ э(н) фи́льм. жё нэ па эмэ рёгардэ лё фи́льм')])])
